import{_ as t,o as i,c as o,a2 as l}from"./chunks/framework.DaGSOal_.js";const c=JSON.parse('{"title":"Usage Guide","description":"","frontmatter":{"sidebar_position":4},"headers":[],"relativePath":"quick-notes/usage.md","filePath":"quick-notes/usage.md","lastUpdated":1794046641000}'),a={name:"quick-notes/usage.md"};function r(n,e,s,u,h,d){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="usage-guide" tabindex="-1">Usage Guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to &quot;Usage Guide&quot;">​</a></h1><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><h3 id="creating-your-first-viewport-note" tabindex="-1">Creating Your First Viewport Note <a class="header-anchor" href="#creating-your-first-viewport-note" aria-label="Permalink to &quot;Creating Your First Viewport Note&quot;">​</a></h3><ol><li>Open any level in your project</li><li>Right-click anywhere in the Viewport</li><li>Select <strong>&quot;Add Quick Note here&quot;</strong> from the context menu</li><li>Fill in the note dialog: <ul><li><strong>Title:</strong> Short summary (e.g., &quot;Fix lighting here&quot;)</li><li><strong>Description:</strong> Optional details</li><li><strong>Category:</strong> Choose TODO, BUG, INFO, or REMINDER</li><li><strong>Priority:</strong> Set Low, Medium, or High</li><li><strong>Editor Only:</strong> Check to hide during Play-In-Editor</li></ul></li><li>Click <strong>Create</strong></li></ol><p>The note appears as a colored card at that location!</p><h3 id="creating-your-first-blueprint-note" tabindex="-1">Creating Your First Blueprint Note <a class="header-anchor" href="#creating-your-first-blueprint-note" aria-label="Permalink to &quot;Creating Your First Blueprint Note&quot;">​</a></h3><ol><li>Open any Blueprint</li><li>Right-click on any node</li><li>Select <strong>&quot;Add Quick Note here&quot;</strong></li><li>Fill in the same dialog as viewport notes</li><li>Click <strong>Create</strong></li></ol><p>The note is now attached to that specific node!</p><h2 id="managing-notes-with-the-overview-panel" tabindex="-1">Managing Notes with the Overview Panel <a class="header-anchor" href="#managing-notes-with-the-overview-panel" aria-label="Permalink to &quot;Managing Notes with the Overview Panel&quot;">​</a></h2><h3 id="opening-the-overview-panel" tabindex="-1">Opening the Overview Panel <a class="header-anchor" href="#opening-the-overview-panel" aria-label="Permalink to &quot;Opening the Overview Panel&quot;">​</a></h3><p>Go to <strong>Tools → Quick Notes</strong> to open the centralized management panel.</p><h3 id="understanding-the-interface" tabindex="-1">Understanding the Interface <a class="header-anchor" href="#understanding-the-interface" aria-label="Permalink to &quot;Understanding the Interface&quot;">​</a></h3><p>The Overview Panel shows:</p><ul><li>List of all notes in your project</li><li>Search box at the top</li><li>Filter options (Source, Status)</li><li>Buttons for Export and navigation</li></ul><h3 id="searching-notes" tabindex="-1">Searching Notes <a class="header-anchor" href="#searching-notes" aria-label="Permalink to &quot;Searching Notes&quot;">​</a></h3><p>Type in the search box to filter by:</p><ul><li>Note title</li><li>Note description</li><li>Partial matches work</li></ul><h3 id="filtering-notes" tabindex="-1">Filtering Notes <a class="header-anchor" href="#filtering-notes" aria-label="Permalink to &quot;Filtering Notes&quot;">​</a></h3><p><strong>By Source:</strong></p><ul><li>All Notes</li><li>Viewport Only</li><li>Blueprint Only</li></ul><p><strong>By Status:</strong></p><ul><li>All</li><li>Unresolved Only</li><li>Resolved Only</li></ul><h3 id="jumping-to-notes" tabindex="-1">Jumping to Notes <a class="header-anchor" href="#jumping-to-notes" aria-label="Permalink to &quot;Jumping to Notes&quot;">​</a></h3><p>Click any note in the list:</p><ul><li><strong>Viewport notes:</strong> Camera moves to the note&#39;s location</li><li><strong>Blueprint notes:</strong> Opens Blueprint Editor and focuses on the node</li></ul><h3 id="marking-notes-as-resolved" tabindex="-1">Marking Notes as Resolved <a class="header-anchor" href="#marking-notes-as-resolved" aria-label="Permalink to &quot;Marking Notes as Resolved&quot;">​</a></h3><ol><li>Select a note in the Overview Panel</li><li>Click <strong>Mark as Resolved</strong> button</li><li>Note stays in history but is marked complete</li><li>Filter to hide resolved notes when focusing on active work</li></ol><h3 id="deleting-notes" tabindex="-1">Deleting Notes <a class="header-anchor" href="#deleting-notes" aria-label="Permalink to &quot;Deleting Notes&quot;">​</a></h3><ol><li>Select a note</li><li>Click <strong>Delete</strong> button</li><li>Confirm deletion</li><li>Note is permanently removed</li></ol><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><h3 id="level-design-bug-tracking" tabindex="-1">Level Design Bug Tracking <a class="header-anchor" href="#level-design-bug-tracking" aria-label="Permalink to &quot;Level Design Bug Tracking&quot;">​</a></h3><p>During playtesting:</p><ol><li>Play your level</li><li>When you spot an issue, pause</li><li>Navigate to the problem area</li><li>Right-click and add a BUG note</li><li>Set priority based on severity</li><li>Continue playtesting</li><li>Later, open Overview Panel to see all bugs</li><li>Fix them one by one, marking as resolved</li></ol><h3 id="blueprint-refactoring" tabindex="-1">Blueprint Refactoring <a class="header-anchor" href="#blueprint-refactoring" aria-label="Permalink to &quot;Blueprint Refactoring&quot;">​</a></h3><p>When working on complex Blueprints:</p><ol><li>Review your Blueprint logic</li><li>Add TODO notes on nodes that need work: <ul><li>&quot;Optimize this loop&quot;</li><li>&quot;Add error handling&quot;</li><li>&quot;Clean up temp variables&quot;</li></ul></li><li>Continue building functionality</li><li>Later, use Overview Panel to find all refactoring tasks</li><li>Tackle them systematically</li></ol><h3 id="team-handoff" tabindex="-1">Team Handoff <a class="header-anchor" href="#team-handoff" aria-label="Permalink to &quot;Team Handoff&quot;">​</a></h3><p>When passing work to another developer:</p><ol><li>Add INFO notes explaining key decisions</li><li>Add TODO notes for remaining work</li><li>Add REMINDER notes for important deadlines</li><li>Export all notes to .txt</li><li>Share the file with team member</li><li>They can reference notes while working</li></ol><h3 id="pre-milestone-cleanup" tabindex="-1">Pre-Milestone Cleanup <a class="header-anchor" href="#pre-milestone-cleanup" aria-label="Permalink to &quot;Pre-Milestone Cleanup&quot;">​</a></h3><p>Before shipping or major milestones:</p><ol><li>Open Overview Panel</li><li>Filter to show all unresolved notes</li><li>Review each one: <ul><li>Fix critical bugs</li><li>Complete important TODOs</li><li>Mark &quot;nice-to-haves&quot; as resolved (defer to next milestone)</li></ul></li><li>Export final list for documentation</li><li>Archive the export with milestone files</li></ol><h3 id="asset-review" tabindex="-1">Asset Review <a class="header-anchor" href="#asset-review" aria-label="Permalink to &quot;Asset Review&quot;">​</a></h3><p>When reviewing levels or systems:</p><ol><li>Walk through level/system</li><li>Add notes for improvements: <ul><li>&quot;Add more detail here&quot;</li><li>&quot;Performance issue - too many lights&quot;</li><li>&quot;Polish pass needed&quot;</li></ul></li><li>Categorize as TODO or INFO</li><li>Set appropriate priorities</li><li>Work through high-priority items first</li></ol><h2 id="advanced-tips" tabindex="-1">Advanced Tips <a class="header-anchor" href="#advanced-tips" aria-label="Permalink to &quot;Advanced Tips&quot;">​</a></h2><h3 id="organize-by-priority" tabindex="-1">Organize by Priority <a class="header-anchor" href="#organize-by-priority" aria-label="Permalink to &quot;Organize by Priority&quot;">​</a></h3><p>Use priorities strategically:</p><ul><li><strong>High:</strong> Must be done before shipping</li><li><strong>Medium:</strong> Should be done but not blocking</li><li><strong>Low:</strong> Polish and nice-to-haves</li></ul><h3 id="use-categories-effectively" tabindex="-1">Use Categories Effectively <a class="header-anchor" href="#use-categories-effectively" aria-label="Permalink to &quot;Use Categories Effectively&quot;">​</a></h3><ul><li><strong>TODO:</strong> Active work items</li><li><strong>BUG:</strong> Things that are broken</li><li><strong>INFO:</strong> Documentation and context</li><li><strong>REMINDER:</strong> Time-sensitive or easy-to-forget tasks</li></ul><h3 id="editor-only-toggle" tabindex="-1">Editor-Only Toggle <a class="header-anchor" href="#editor-only-toggle" aria-label="Permalink to &quot;Editor-Only Toggle&quot;">​</a></h3><p>Use &quot;Editor Only&quot; for:</p><ul><li>Visual aids during development</li><li>Notes that would break immersion during testing</li><li>Temporary markers</li></ul><p>Don&#39;t use it for:</p><ul><li>Important bugs that need testing in PIE</li><li>Performance markers you want to see during play</li></ul><h3 id="blueprint-note-best-practices" tabindex="-1">Blueprint Note Best Practices <a class="header-anchor" href="#blueprint-note-best-practices" aria-label="Permalink to &quot;Blueprint Note Best Practices&quot;">​</a></h3><p>✅ <strong>Do:</strong></p><ul><li>Add notes to complex logic</li><li>Mark nodes that need optimization</li><li>Document why you made certain decisions</li></ul><p>❌ <strong>Don&#39;t:</strong></p><ul><li>Add too many notes (clutters the graph)</li><li>Leave vague notes without context</li><li>Forget to mark as resolved when done</li></ul><h3 id="export-regularly" tabindex="-1">Export Regularly <a class="header-anchor" href="#export-regularly" aria-label="Permalink to &quot;Export Regularly&quot;">​</a></h3><p>Create periodic exports:</p><ul><li>Weekly for active projects</li><li>Before major milestones</li><li>When changing team members</li><li>For sprint reviews</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="note-doesn-t-appear" tabindex="-1">Note Doesn&#39;t Appear <a class="header-anchor" href="#note-doesn-t-appear" aria-label="Permalink to &quot;Note Doesn&#39;t Appear&quot;">​</a></h3><p><strong>Cause:</strong> Editor-only mode enabled and you&#39;re in PIE</p><p><strong>Solution:</strong> Exit Play-In-Editor mode</p><h3 id="can-t-find-a-note" tabindex="-1">Can&#39;t Find a Note <a class="header-anchor" href="#can-t-find-a-note" aria-label="Permalink to &quot;Can&#39;t Find a Note&quot;">​</a></h3><p><strong>Cause:</strong> Filtered out or deleted</p><p><strong>Solution:</strong></p><ul><li>Check filter settings in Overview Panel</li><li>Make sure &quot;Show Resolved&quot; is enabled</li><li>Try searching by keyword</li></ul><h3 id="blueprint-note-lost" tabindex="-1">Blueprint Note Lost <a class="header-anchor" href="#blueprint-note-lost" aria-label="Permalink to &quot;Blueprint Note Lost&quot;">​</a></h3><p><strong>Cause:</strong> Node was deleted or Blueprint was refactored</p><p><strong>Solution:</strong></p><ul><li>Check Overview Panel - note may show as orphaned</li><li>Note is preserved even if node is gone</li><li>Can be deleted manually if no longer needed</li></ul><h3 id="error-code-qn-xxx-in-output-log" tabindex="-1">Error Code QN-XXX in Output Log <a class="header-anchor" href="#error-code-qn-xxx-in-output-log" aria-label="Permalink to &quot;Error Code QN-XXX in Output Log&quot;">​</a></h3><p><strong>Solution:</strong></p><ul><li>Note the error code</li><li>Check Output Log for details</li><li>Submit the error code via the <a href="https://deblx.com/help" target="_blank" rel="noreferrer">Deblx Help Center</a></li><li>Or ask in <a href="https://discord.gg/UJCnVjwTTt" target="_blank" rel="noreferrer">Deblx Dev Discord</a></li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><p>Currently, Quick Notes uses context menus for creation. Keyboard shortcuts may be added in future updates based on user feedback!</p>',81)])])}const p=t(a,[["render",r]]);export{c as __pageData,p as default};
